SCALEKIT_RESOURCE_ID = "res_123"
RESOURCE = "https://mcp.example.com"
SCOPES_SUPPORTED = ["todo:read", "todo:write"]

scalekit_client = ScalekitClient(environment_url=SCALEKIT_ENVIRONMENT_URL)

app = FastAPI()


@app.get("/.well-known/oauth-protected-resource")
def oauth_protected_resource():
    return {
        "authorization_servers": [f"{SCALEKIT_ENVIRONMENT_URL}/resources/{SCALEKIT_RESOURCE_ID}"],
        "bearer_methods_supported": ["header"],
        "resource": RESOURCE,
        "scopes_supported": SCOPES_SUPPORTED,
    }


def _normalize_scopes(scopes_value: Optional[object]) -> Iterable[str]:
    if scopes_value is None:
        return []
    if isinstance(scopes_value, str):
        return [scope for scope in scopes_value.split(" ") if scope]
    if isinstance(scopes_value, (list, tuple, set)):
        return [str(scope) for scope in scopes_value]
    return []


@app.middleware("http")
async def verify_bearer_token(request: Request, call_next):
    if request.url.path == "/.well-known/oauth-protected-resource":
        return await call_next(request)

    authorization = request.headers.get("authorization")
    if not authorization or not authorization.lower().startswith("bearer "):
        return JSONResponse(status_code=401, content={"detail": "Missing bearer token"})

    token = authorization.split(" ", 1)[1].strip()
    if not token:
        return JSONResponse(status_code=401, content={"detail": "Missing bearer token"})

    try:
        validation = scalekit_client.validate_token(token)
    except Exception as exc:  # pragma: no cover - pass through Scalekit errors
        return JSONResponse(status_code=401, content={"detail": str(exc)})

    request.state.token = validation
    return await call_next(request)


@app.post("/tools/execute")
def execute_tool(request: Request):
    token_payload = getattr(request.state, "token", {})
    scopes = set(_normalize_scopes(token_payload.get("scopes") or token_payload.get("scope")))

    if "todo:write" not in scopes:
        raise HTTPException(status_code=403, detail="Missing todo:write scope")

    return {"status": "success"}


